INSERT OR REPLACE INTO normative_rfcs (rfc_id, slug, title, working_group, status, hourglass_layer, statutory_anchors_json, summary_civic, full_markdown_body, openapi_contract_path, json_schema_uri, sha256_digest, updated_at_utc) VALUES ('NS-RFC-003', 'ns-rfc-003-workflow-state-and-safe-retry', 'Deterministic Workflow State Machine & Safe Same-Reference Retry', 'WG-01', 'RATIFIED_NORMATIVE', 'Layer 4', '["CBN Payment Guidelines"]', '3\. NS-RFC-003: Deterministic Workflow State Machine & Safe Same-Reference Retry**', '# **3\. NS-RFC-003: Deterministic Workflow State Machine & Safe Same-Reference Retry**

* **Status:** CANDIDATE STANDARD (Stage 3\)  
* **Working Group:** WG-01  
* **Target Gap Mechanisms:** `MECH-03` (Semantic Gap), `MECH-04` (Transaction Gap), `MECH-06` (Operational Continuity)

## **3.1 The 6 Canonical Operation States**

To eliminate double-debiting on payment transfers (`IND-01`), duplicate tax filings (`IND-05`), and ambiguous registry submissions (`IND-21`), every Confluence adapter MUST implement this exact 6-state finite state machine:

1. `INITIATED`: Request validated against schema; `cop_` ULID assigned; persisted to local durable log.  
2. `ACCEPTED_PENDING`: Upstream provider acknowledged receipt (`HTTP 202`), final business outcome pending.  
3. `UNKNOWN_TIMEOUT`: Network timeout, HTTP 502/504, or lost connection occurred *after* payload transmission. **Normative Rule:** An `UNKNOWN_TIMEOUT` state MUST NEVER be coerced automatically to `FAILED_TERMINAL`.  
4. `RESOLVED_SUCCESS`: Verified terminal success accompanied by a retained `SureEvidence` receipt digest.  
5. `RESOLVED_REVERSED`: Upstream operation initially succeeded or pended but was subsequently reversed/refunded; linked to reversal evidence.  
6. `FAILED_TERMINAL`: Upstream provider explicitly rejected the request prior to execution, or reconciliation proved zero execution occurred.

## **3.2 Safe Same-Reference Retry Invariant**

* While an operation is in `ACCEPTED_PENDING` or `UNKNOWN_TIMEOUT`, a retry MUST reuse the original `customer_reference` and `X-NgStack-Idempotency-Key`.  
* Generating a new provider reference or failing over to a second provider while the first operation remains in `UNKNOWN_TIMEOUT` is STRICTLY PROHIBITED (`HTTP 409 UNRESOLVED_OPERATION_LOCK`).
', 'specs/openapi/v2026/', 'https://nigeriastack.org/schemas/v2026/', 'f1e83d40f4553d6bd4e06d6436a41d843103ab224b752445c0122ba37f137aaa', '2026-11-16T00:00:00Z');
INSERT INTO ngstack_global_search_fts (entity_type, entity_id, canonical_url, title_civic, body_searchable, statutory_tags) VALUES ('RFC', 'NS-RFC-003', '/rfcs/NS-RFC-003', 'Deterministic Workflow State Machine & Safe Same-Reference Retry', '3\. NS-RFC-003: Deterministic Workflow State Machine & Safe Same-Reference Retry**', 'CBN Payment Guidelines');
INSERT OR REPLACE INTO normative_rfcs (rfc_id, slug, title, working_group, status, hourglass_layer, statutory_anchors_json, summary_civic, full_markdown_body, openapi_contract_path, json_schema_uri, sha256_digest, updated_at_utc) VALUES ('NS-RFC-004', 'ns-rfc-004-kioskbase-offline-hlc-crdt-sync', 'KioskBase Offline-First SQLite WASM & Hybrid Logical Clock (HLC) CRDT Sync', 'WG-05', 'RATIFIED_NORMATIVE', 'Layer 1 & 3', '["NDPA 2023 ss. 30-31"]', '4\. NS-RFC-004: KioskBase Offline-First SQLite WASM & Hybrid Logical Clock (HLC) CRDT Sync**', '# **4\. NS-RFC-004: KioskBase Offline-First SQLite WASM & Hybrid Logical Clock (HLC) CRDT Sync**

* **Status:** CANDIDATE STANDARD (Stage 3\)  
* **Working Group:** WG-05 (Sub-National Registries, Health, Education & Smart Grids)  
* **Namespace URI:** `urn:ngstack:kioskbase:v2026`  
* **Target Gap Mechanisms:** `MECH-02` (Sub-National Coverage Gap), `MECH-06` (Offline Continuity Gap)

## **4.1 Client Footprint & Local Storage Invariants**

1. **Payload Budget:** Any `KioskBase`\-compliant Progressive Web App (used across 36 State Judiciaries, Magistracies, Deeds Registries, Rural PHCs, and 774 LGA `MarketCollect` kiosks) MUST ship an initial shell \< 35 KB gzipped with zero external webfont blocking when `Save-Data: on` is present.  
2. **Encrypted Local SQLite WASM:** Client nodes SHALL persist records locally in Origin-Private File System (OPFS) SQLite WASM tables with a `crdt_hlc_oplog` delta table (`kbd_` ULID).

## **4.2 Hybrid Logical Clock (HLC) Format & 300-Second Drift Rule (`RED-CNT-04`)**

* Every offline mutation MUST generate a monotonic HLC timestamp: `<physical_epoch_ms_48bit>:<logical_counter_16bit>:<node_fido2_fingerprint_16char>`.  
* **Hardware Clock Drift Disclosure (`RED-CNT-04`):** If an unpowered registry device''s hardware real-time clock drifts by \> 300 seconds against cellular NTP or GPS time upon reconnection, the delta envelope MUST be tagged `clockSyncStatus: "DEGRADED_LOCAL_HLC"`. Such records MAY sync to staging queues but MUST NOT receive a final enrolled judicial or cadastral time-priority seal until NTP/GPS resynchronization is attested.  
* **Kernel Privacy Quarantine (`NDPA Gate 10`):** Local and cloud databases MUST enforce PostgreSQL 17 `FORCE ROW LEVEL SECURITY` (and client SQLite triggers) locking matrimonial (`HD/`, `WD/`), juvenile, adoption, and clinical HIV/mental-health records inside `visibility_tier = ''INTERNAL_RESTRICTED_NDPA''`. Unsealed drafts and restricted records MUST NEVER enter public sync outboxes.
