INSERT INTO ngstack_global_search_fts (entity_type, entity_id, canonical_url, title_civic, body_searchable, statutory_tags) VALUES ('RFC', 'NS-RFC-004', '/rfcs/NS-RFC-004', 'KioskBase Offline-First SQLite WASM & Hybrid Logical Clock (HLC) CRDT Sync', '4\. NS-RFC-004: KioskBase Offline-First SQLite WASM & Hybrid Logical Clock (HLC) CRDT Sync**', 'NDPA 2023 ss. 30-31');
INSERT OR REPLACE INTO normative_rfcs (rfc_id, slug, title, working_group, status, hourglass_layer, statutory_anchors_json, summary_civic, full_markdown_body, openapi_contract_path, json_schema_uri, sha256_digest, updated_at_utc) VALUES ('NS-RFC-005', 'ns-rfc-005-sureevidence-act-s84-credentials', 'SureEvidence Cryptographic Regularity & Evidence Act 2011 Section 84 Credentials', 'WG-02', 'RATIFIED_NORMATIVE', 'Layer 3', '["Evidence Act 2011 ss. 84 & 106"]', '5\. NS-RFC-005: SureEvidence Cryptographic Regularity & Evidence Act 2011 Section 84 Credentials (`SureProof`)**', '# **5\. NS-RFC-005: SureEvidence Cryptographic Regularity & Evidence Act 2011 Section 84 Credentials (`SureProof`)**

* **Status:** CANDIDATE STANDARD (Stage 3\)  
* **Working Group:** WG-02 (SureEvidence Cryptographic Trust, Legal ASTs & Admissibility)  
* **Namespace URI:** `urn:ngstack:sure-evidence:v2026`  
* **Statutory Anchor:** Evidence Act 2011, Section 84(1)–(4) & Section 106; W3C Verifiable Credentials Data Model 2.0.  
* **Target Gap Mechanism:** `MECH-05` (Trust & Evidentiary Provenance Gap)

## **5.1 Mandatory Section 84(4) Certificate Structure**

To prevent electronic printouts, Certified True Copies (CTCs), tax receipts, medical claims, land search certificates, or LGA Indigene certificates (IndigeneProof) from being rejected in Nigerian courts under Section 84 of the Evidence Act 2011, every `SureEvidence` credential (`s84_` ULID) MUST embed three normative blocks:

1. **`issuingAuthority`:** `jurisdictionSlug` (e.g., `highcourt.lagosstate.gov.ng` or `amac.fct.gov.ng`), `divisionOrDepartment`, `certifyingOfficerName`, `certifyingOfficerRole`, and `fido2KeyId`.  
2. **`deviceRegularityAttestation` (Section 84(2) & (4) Compliance):**  
   * `hardwareFingerprintSha256`: 64-char hex digest of the certifying workstation/HSM.  
   * `operatingConditionState`: `"NORMAL_CONTINUOUS_OPERATION"` or `"RECOVERED_OFFLINE_SYNC"`.  
   * `monotonicSealCounter`: Strictly increasing integer per hardware key.  
   * `clockSyncSource`: `"GPS_HARDWARE_RTC"` or `"CELLULAR_NTP_VERIFIED"`.  
   * `statutoryDeclarationText`: Verbatim statutory attestation under Section 84(4) Evidence Act 2011 stating that the computer device was operating properly at all material times.  
3. **`cryptographicSeal`:**  
   * `payloadSha256Digest`: 64-char hex SHA-256 digest of the canonical document bytes.  
   * `signatureAlgorithm`: `"Ed25519"` or `"ECDSA_P256_FIDO2"`.  
   * `signatureBase64Url`: Cryptographic signature verifiable offline against the issuer''s public key encoded inside a 300-DPI QR code (`ngstack://verify/s84_{ulid}?sig=...`).

## **5.2 Append-Only Merkle Transparency Log & Independent Public Auditability (RED-AUDIT-03)**

* Every `SureEvidence` registry node MUST publish a daily signed SHA-256 Merkle root (`GET /v1/audit/merkle-root`) over all issued `s84_` credential digests and revocation events, enabling external researchers, auditors, and citizens to verify zero silent record alteration without privileged database access.
', 'specs/openapi/v2026/', 'https://nigeriastack.org/schemas/v2026/', '3808991d9f451c43d2345175a28ea2dd6f892cbed7e71e0454d96a91c4cc3761', '2026-11-16T00:00:00Z');
INSERT INTO ngstack_global_search_fts (entity_type, entity_id, canonical_url, title_civic, body_searchable, statutory_tags) VALUES ('RFC', 'NS-RFC-005', '/rfcs/NS-RFC-005', 'SureEvidence Cryptographic Regularity & Evidence Act 2011 Section 84 Credentials', '5\. NS-RFC-005: SureEvidence Cryptographic Regularity & Evidence Act 2011 Section 84 Credentials (`SureProof`)**', 'Evidence Act 2011 ss. 84 & 106');
INSERT OR REPLACE INTO normative_rfcs (rfc_id, slug, title, working_group, status, hourglass_layer, statutory_anchors_json, summary_civic, full_markdown_body, openapi_contract_path, json_schema_uri, sha256_digest, updated_at_utc) VALUES ('NS-RFC-006', 'ns-rfc-006-clearam-consent-envelopes', 'ClearanceMesh (ClearAm) Multi-Sectoral Consent & Lawful-Purpose Envelopes', 'WG-03', 'RATIFIED_NORMATIVE', 'Layer 4', '["NDPA 2023 ss. 24-37", "NDPC GAID 2025"]', '1\. NS-RFC-006: ClearanceMesh (`ClearAm`) Multi-Sectoral Consent & Lawful-Purpose Envelopes**', '# **1\. NS-RFC-006: ClearanceMesh (`ClearAm`) Multi-Sectoral Consent & Lawful-Purpose Envelopes**

* **Status:** CANDIDATE STANDARD (Stage 3\)  
* **Working Group:** WG-03 (ClearanceMesh Privacy, Open Finance & Fiscal Invariance)  
* **Namespace URI:** `urn:ngstack:clearam:v2026`  
* **Statutory Anchor:** Nigeria Data Protection Act (NDPA) 2023, Sections 24, 25, 28, 30, 31, and 37; NDPC General Application and Implementation Directive (GAID) 2025; CBN Open Banking Operational Guidelines.  
* **Target Gap Mechanisms:** `MECH-01` (Source-Access Gap), `MECH-05` (Trust/Provenance Gap)

## **1.1 Normative Envelope Structure (`clm_` ULID)**

Every cross-institutional request for personal or corporate-restricted records across any of the 32 industries MUST carry a signed `ClearAm` consent envelope (clm\_\[0-9A-HJKMNP-TV-Z\]{26}) containing:

1. **`dataPrincipal`:**  
   * `identifierType`: `"NIN"` \| `"BVN"` \| `"RC_NUMBER"` \| `"TIN"` \| `"SCN"` \| `"NHIA_ID"`.  
   * `saltedIdentityHashSha256`: 64-char hex SHA-256 digest of the identifier; raw NIN/BVN strings MUST NOT be transmitted in cleartext headers.  
2. **`lawfulBasisAndPurpose` (NDPA s. 25 Compliance):**  
   * `lawfulBasis`: `"EXPLICIT_DATA_SUBJECT_CONSENT"` \| `"STATUTORY_PUBLIC_MANDATE"` \| `"OPEN_COURT_PUBLIC_INTEREST"` \| `"CONTRACTUAL_PERFORMANCE"`.  
   * `purposeCode`: Must match a registered template in `nigeriastack/clearam-consent-templates` (e.g., `FIN-MSME-CREDIT-UNDERWRITING`, `LAW-LITIGATION-CLEARANCE`, `HLTH-PATIENT-RECORD-TRANSFER`, `EDU-DEGREE-VERIFICATION`, `AGRI-FARM-INPUT-FINANCING`, `LGA-INDIGENE-AND-VITAL-ATTESTATION`).  
3. **`dataProvidersAndScopes`:**  
   * Explicit allow-list of target `providerCategory` nodes and field-level `permittedScopes` (e.g., `["OPEN_BANKING_CASHFLOW_90D", "COURT_ENCUMBRANCE_CHECK", "LAND_LIS_PENDENS_STATUS"]`).  
4. **`temporalBoundsAndExpiry` (`RED-CNT-02` Invariant):**  
   * `issuedAtUtc`, `validUntilUtc`, `maxRetentionDays`, and `maxQueryFrequency`.  
   * **Mandatory Expiry Rejection Rule (`RED-CNT-02`):** Any Data Information Provider (DIP) or gateway receiving a request whose `validUntilUtc < current_utc_timestamp` MUST immediately abort processing with `HTTP 403 CLEARAM_ARTIFACT_EXPIRED` and MUST NOT introspect or cache the downstream payload.

## **1.2 Right to Exit & \< 60-Second Consent Revocation SLA (01 Exit / RED-AUDIT-01)**

Any Data Subject revoking a `ClearAm` consent token (`DELETE /v1/clearam/consents/{clm_ulid}`) MUST have that revocation propagated across all participating gateways within 60 seconds, causing any subsequent query using that token to abort at the perimeter with `HTTP 403 CLEARAM_ARTIFACT_REVOKED` and zero database queries.
