INSERT INTO ngstack_global_search_fts (entity_type, entity_id, canonical_url, title_civic, body_searchable, statutory_tags) VALUES ('RFC', 'NS-RFC-007', '/rfcs/NS-RFC-007', 'OpenMarket (MarketLink) Decentralized Commerce, Catalog & Haulage Protocol', '2\. NS-RFC-007: OpenMarket (`MarketLink`) Decentralized Commerce, Catalog & Haulage Protocol**', 'FCCPA 2018');
INSERT OR REPLACE INTO normative_rfcs (rfc_id, slug, title, working_group, status, hourglass_layer, statutory_anchors_json, summary_civic, full_markdown_body, openapi_contract_path, json_schema_uri, sha256_digest, updated_at_utc) VALUES ('NS-RFC-008', 'ns-rfc-008-givepower-agent-delegation-protocol', 'Warrant & Mandate (GivePower) Autonomous Agent Delegation & MCP Safety Protocol', 'WG-06', 'RATIFIED_NORMATIVE', 'Layer 4', '["NDPA 2023 s. 37"]', '3\. NS-RFC-008: Warrant & Mandate (`GivePower`) Autonomous Agent Delegation & MCP Safety Protocol**', '# **3\. NS-RFC-008: Warrant & Mandate (`GivePower`) Autonomous Agent Delegation & MCP Safety Protocol**

* **Status:** CANDIDATE STANDARD (Stage 3\)  
* **Working Group:** WG-06 (GivePower Agentic AI Delegation, MCP Sandboxing & Conformance)  
* **Namespace URI:** `urn:ngstack:givepower:v2026`  
* **Statutory Anchor:** NDPA 2023 Section 37 (Automated Decision-Making & Human Intervention); AAIF Model Context Protocol (MCP) JSON-RPC 2.0.  
* **Target Gap Mechanisms:** `MECH-04` (Transaction Gap), `MECH-05` (Trust Gap), `MECH-08` (Implementation Gap)

## **3.1 Three Mandatory Agentic Safety Guardrails**

Every MCP server or autonomous AI agent interacting with Nigerian public or enterprise systems under GivePower (gpw\_ ULID) MUST enforce:

1. **Guardrail 1 — Read-Only Default Sandboxing:** All registered MCP tools MUST declare `"defaultExecutionMode": "READ_ONLY_DEFAULT"`. Autonomous agents MAY query public statutes, verify `SureEvidence` QR digests, or check non-mutating operation statuses (`GET /v1/mcp/operations/{cop_ulid}`), but MUST NOT execute state-mutating calls by default.  
2. **Guardrail 2 — Cryptographic Human Countersignature (`NDPA s. 37`):** Any state-mutating agent action (initiating a funds transfer, lodging a court filing, modifying a registry record, or granting consent) MUST include a non-expired `humanCountersignatureEd25519` signed by the delegating human principal''s FIDO2/WebAuthn key over the exact action parameters.  
3. **Guardrail 3 — Two-Phase HTTP 402 (`x402`) Micro-Settlement Escrow (`RED-CNT-03` Invariant):**  
   * Remember: `nigeriastack.org` never processes payments; it defines the verification contract for downstream relays.  
   * When an MCP tool call requires an HTTP 402 (`x402`) sub-cent micro-settlement, the payment token MUST remain in **two-phase cryptographic escrow** (`ESCROW_LOCKED`) and MAY release to the downstream tool provider ONLY after the caller receives a schema-valid JSON-RPC 2.0 `200 OK` response carrying a valid `SureEvidence` payload hash. If the downstream provider times out or returns a `5xx` error, the escrow token automatically reverts to the caller''s budget wallet.
', 'specs/openapi/v2026/', 'https://nigeriastack.org/schemas/v2026/', 'f81a100e8ce50bf75500dc174221d5914f64e8445b54e957b8982d6c3a3d6bbb', '2026-11-16T00:00:00Z');
INSERT INTO ngstack_global_search_fts (entity_type, entity_id, canonical_url, title_civic, body_searchable, statutory_tags) VALUES ('RFC', 'NS-RFC-008', '/rfcs/NS-RFC-008', 'Warrant & Mandate (GivePower) Autonomous Agent Delegation & MCP Safety Protocol', '3\. NS-RFC-008: Warrant & Mandate (`GivePower`) Autonomous Agent Delegation & MCP Safety Protocol**', 'NDPA 2023 s. 37');
INSERT OR REPLACE INTO normative_rfcs (rfc_id, slug, title, working_group, status, hourglass_layer, statutory_anchors_json, summary_civic, full_markdown_body, openapi_contract_path, json_schema_uri, sha256_digest, updated_at_utc) VALUES ('NS-RFC-009', 'ns-rfc-009-treasury-passthrough-invariance', 'SplitDirect Public Treasury Pass-Through & Fiscal Invariance Protocol', 'WG-03', 'RATIFIED_NORMATIVE', 'Layer 2', '["1999 CFRN s. 121(3)", "SC/CV/343/2024"]', '4\. NS-RFC-009: `SplitDirect` Public Treasury Pass-Through & Fiscal Invariance Protocol**', '# **4\. NS-RFC-009: `SplitDirect` Public Treasury Pass-Through & Fiscal Invariance Protocol**

* **Status:** CANDIDATE STANDARD (Stage 3\)  
* **Working Group:** WG-03  
* **Namespace URI:** `urn:ngstack:splitdirect:v2026`  
* **Statutory Anchor:** 1999 Constitution of the Federal Republic of Nigeria (as amended), Section 121(3) (Financial Autonomy of State Judiciaries & Legislatures), Section 162, & Section 7(1) / Fourth Schedule; Supreme Court Judgment `AG Federation v. AG Abia State & 35 Ors (SC/CV/343/2024)`; Nigeria Revenue Service (NRS) ATRS e-Invoicing Standard.  
* **Target Gap Mechanisms:** `MECH-02` (Sub-National Coverage), `MECH-04` (Transaction Gap), `MECH-05` (Audit Provenance), `MECH-07` (Commercial Capture)

## **4.1 Zero Private Escrow of Public Statutory Revenue (`RED-CNT-01` Invariant)**

To eliminate the primary institutional barrier to public-sector digitization (fear by State Attorneys General, Chief Judges, State IRS Chairmen, and 774 LGA Treasurers that private technology vendors will intercept or escrow public Internally Generated Revenue \[IGR\]):

1. **Hard Invariant (`platform_escrow_amount_kobo == 0`):** No private Technical Service Provider (TSP) or software concessionaire implementing `nigeriastack.org` specifications MAY collect, pool, or hold statutory filing fees, probate assessments, land registration charges, state taxes, or LGA `MarketCollect` / `TenementRate` levies in a private corporate bank account.  
2. **Deterministic Gateway Split Schema (`revenue_split_rule`):** Every public-revenue payment payload routed to NIBSS, Remita, Interswitch, or a CBN-licensed payment gateway MUST declare an immutable split array at initiation:  
   * `statutoryPrincipalSplit`: `100%` of the statutory fee schedule routed directly to the verified `TreasurySingleAccount (TSA)`, `StateConsolidatedRevenueFund (CRF)`, `StateJudiciaryAutonomyAccount (CFRN s.121(3))`, or `DirectLgaTreasuryAccount (SC/CV/343/2024)`.  
   * `tspConvenienceFeeSplit` *(Optional)*: Any contractually gazetted technology convenience fee is split at the payment gateway level as a separate line item and never commingled with statutory principal sums.  
3. **Cryptographic Settlement Verification Before Sealing:** A `KioskBase` or `SureEvidence` registry node MUST verify the signed gateway settlement webhook (`settlementStatus == "SETTLED_DIRECT_TO_TREASURY"`) before minting a final enrolled seal on a fee-bearing document.  
4. **Public Merkle Treasury Audit Log (03 Audit / RED-AUDIT-03):** Every `SplitDirect` gateway and 774-LGA / Court revenue node MUST publish an append-only SHA-256 Merkle root (`GET /v1/audit/treasury-merkle-root`) over daily statutory split receipts so State/Federal Auditors General, NFIU, and civic monitors (Cluster 7\) can mathematically verify `platform_escrow_amount_kobo == 0` and `state_intermediary_escrow_kobo == 0` without exposing payer PII.
', 'specs/openapi/v2026/', 'https://nigeriastack.org/schemas/v2026/', 'a61cd8e7a6d68dd7b96a677d2d94b16c147197cf8dbf10acaa18033097fd6811', '2026-11-16T00:00:00Z');
INSERT INTO ngstack_global_search_fts (entity_type, entity_id, canonical_url, title_civic, body_searchable, statutory_tags) VALUES ('RFC', 'NS-RFC-009', '/rfcs/NS-RFC-009', 'SplitDirect Public Treasury Pass-Through & Fiscal Invariance Protocol', '4\. NS-RFC-009: `SplitDirect` Public Treasury Pass-Through & Fiscal Invariance Protocol**', '1999 CFRN s. 121(3) SC/CV/343/2024');
INSERT OR REPLACE INTO normative_rfcs (rfc_id, slug, title, working_group, status, hourglass_layer, statutory_anchors_json, summary_civic, full_markdown_body, openapi_contract_path, json_schema_uri, sha256_digest, updated_at_utc) VALUES ('NS-RFC-010', 'ns-rfc-010-tradecorridor-customs-mesh', 'TradeCorridor (PassCargo) Cross-Border Trade, Customs & Port Interoperability Framework', 'WG-04', 'RATIFIED_NORMATIVE', 'Layer 4', '["NCS Act 2023", "ETLS Protocols"]', '1\. NS-RFC-010: TradeCorridor (`PassCargo`) Cross-Border Trade, Customs & Port Interoperability Framework**', '# **1\. NS-RFC-010: TradeCorridor (`PassCargo`) Cross-Border Trade, Customs & Port Interoperability Framework**

* **Status:** CANDIDATE STANDARD (Stage 3\)  
* **Working Group:** WG-04 (OpenMarket Commerce, Logistics, Trade & Agrarian Corridors)  
* **Namespace URI:** `urn:ngstack:passcargo:v2026`  
* **Statutory Anchor:** Nigeria Customs Service (NCS) Act 2023; Nigerian Ports Authority (NPA) Act; SON Act; NAFDAC Act; ECOWAS Trade Liberalization Scheme (ETLS) Protocols.  
* **Target Gap Mechanisms:** `MECH-01` (Source-Access Gap), `MECH-03` (Semantic Gap), `MECH-04` (Transaction Gap)

## **1.1 Multi-Agency Single-Submission Event Chain**

To eliminate repetitive manual re-keying of cargo manifests across 7+ port and border agencies (`IND-10`), `PassCargo` specifies a cryptographically linked event chain over Confluence (cop\_ ULID) asynchronous pairs:

1. **`CargoManifestRegistered`:** Links the Single Goods Declaration (SGD) / NCS B''Odogwu reference with the master Bill of Lading (`BL`) SHA-256 digest.  
2. **`RegulatoryClearanceAttached`:** Appends issuer-signed `SureEvidence` (`s84_` ULID) credentials from SON (`SONCAP`), NAFDAC, Quarantine (`NAQS`), and NESREA without duplicating raw agency databases.  
3. **`TerminalExitAndWaybillToken`:** Generates an offline-verifiable 300-DPI Ed25519 QR token (`ngstack://verify/s84_{ulid}`) allowing port gates, FRSC highway patrols, and ECOWAS border posts (Seme-Krake, Illela, Jibiya, Mfum) to verify cargo clearance offline in **\< 50ms**.

---
', 'specs/openapi/v2026/', 'https://nigeriastack.org/schemas/v2026/', 'dbb1acd94d2ddddac4841e4605b970040a052af57b39293058097d4c767ae020', '2026-11-16T00:00:00Z');
INSERT INTO ngstack_global_search_fts (entity_type, entity_id, canonical_url, title_civic, body_searchable, statutory_tags) VALUES ('RFC', 'NS-RFC-010', '/rfcs/NS-RFC-010', 'TradeCorridor (PassCargo) Cross-Border Trade, Customs & Port Interoperability Framework', '1\. NS-RFC-010: TradeCorridor (`PassCargo`) Cross-Border Trade, Customs & Port Interoperability Framework**', 'NCS Act 2023 ETLS Protocols');
INSERT OR REPLACE INTO normative_rfcs (rfc_id, slug, title, working_group, status, hourglass_layer, statutory_anchors_json, summary_civic, full_markdown_body, openapi_contract_path, json_schema_uri, sha256_digest, updated_at_utc) VALUES ('NS-RFC-011', 'ns-rfc-011-ndhx-fhir-health-data-profile', 'Nigeria Digital Health Exchange (NDHX) & SureLearn Verifiable Academic Credentials', 'WG-05', 'RATIFIED_NORMATIVE', 'Layer 1 & 5', '["National Health Act 2014", "NHIA Act 2022"]', '2\. NS-RFC-011: Nigeria Digital Health Exchange (`NDHX`) & `SureLearn` Verifiable Academic Credentials**', '# **2\. NS-RFC-011: Nigeria Digital Health Exchange (`NDHX`) & `SureLearn` Verifiable Academic Credentials**

* **Status:** CANDIDATE STANDARD (Stage 3\)  
* **Working Group:** WG-05 (Sub-National Registries, Health, Education & Smart Grids)  
* **Namespace URIs:** `urn:ngstack:ndhx:v2026` & `urn:ngstack:surelearn:v2026`  
* **Statutory Anchor:** National Health Act 2014; NHIA Act 2022; NDPA 2023 ss. 30–31 (Sensitive Personal Data); NUC / NBTE / WAEC / JAMB Enabling Acts.  
* **Target Gap Mechanisms:** `MECH-01` (Source-Access), `MECH-03` (Semantic), `MECH-05` (Trust/Provenance)

## **2.1 `NDHX` Patient-Consented HL7 FHIR R4 Profile (`IND-19`)**

1. **Mandatory `ClearAm` Sensitive-Data Gate:** No hospital EMR, HMO, pharmacy, or diagnostic lab MAY exchange patient summaries, e-prescriptions (`eRx`), or NHIA/HMO e-claims without a valid `ClearAm` token (`clm_` ULID) carrying `purposeCode: "HLTH-PATIENT-RECORD-TRANSFER"` or `"EMERGENCY_VITAL_CARE"`.  
2. **Offline Ward PHC Synchronization:** Rural Primary Healthcare Centres (PHCs) operating under `LGA-11` (`WardPHC`) MUST support offline `KioskBase` immunization and maternal-health encounter capture with automatic HLC-CRDT sync.

## **2.2 `SureLearn` W3C Verifiable Academic & Professional Credentials (`IND-20`)**

* Universities, Polytechnics, WAEC, NECO, JAMB, NYSC, and professional bodies (NBA, MDCN, COREN, ICAN, TRCN) SHALL issue degree transcripts, discharge certificates, and practicing licenses as W3C Verifiable Credentials v2.0 wrapped in a `SureEvidence` (`s84_` ULID) hardware signature.  
* Employers and foreign embassies verify authenticity offline via the embedded Ed25519 public key without paying recurring scratch-card or manual postal verification fees.

---
', 'specs/openapi/v2026/', 'https://nigeriastack.org/schemas/v2026/', '482eb35f15cea97860d4d72f06c5596861e7b8a0cd10cc45c761bdd37c0416cc', '2026-11-16T00:00:00Z');
INSERT INTO ngstack_global_search_fts (entity_type, entity_id, canonical_url, title_civic, body_searchable, statutory_tags) VALUES ('RFC', 'NS-RFC-011', '/rfcs/NS-RFC-011', 'Nigeria Digital Health Exchange (NDHX) & SureLearn Verifiable Academic Credentials', '2\. NS-RFC-011: Nigeria Digital Health Exchange (`NDHX`) & `SureLearn` Verifiable Academic Credentials**', 'National Health Act 2014 NHIA Act 2022');
INSERT OR REPLACE INTO normative_rfcs (rfc_id, slug, title, working_group, status, hourglass_layer, statutory_anchors_json, summary_civic, full_markdown_body, openapi_contract_path, json_schema_uri, sha256_digest, updated_at_utc) VALUES ('NS-RFC-012', 'ns-rfc-012-agritrust-farm-polygon-standard', 'AgriTrust Smallholder Farm Geopolygon & Negotiable Warehouse Receipt Standard', 'WG-04', 'RATIFIED_NORMATIVE', 'Layer 1 & 5', '["Land Use Act 1978", "SEC Rules"]', '3\. NS-RFC-012: `AgriTrust` Smallholder Farm Geopolygon & Negotiable Warehouse Receipt Standard**', '# **3\. NS-RFC-012: `AgriTrust` Smallholder Farm Geopolygon & Negotiable Warehouse Receipt Standard**

* **Status:** CANDIDATE STANDARD (Stage 3\)  
* **Working Group:** WG-04  
* **Namespace URI:** `urn:ngstack:agritrust:v2026`  
* **Statutory Anchor:** SEC Rules on Commodities Exchanges & Warehouse Receipts; FMARD National Farmer Registry; Land Use Act 1978 (Customary & Statutory Occupancy).  
* **Target Gap Mechanisms:** `MECH-02` (Rural Coverage Gap), `MECH-05` (Collateral Provenance Gap), `MECH-06` (Offline Continuity Gap)

## **3.1 Offline-Capturable GeoJSON Farm Polygons (`IND-15` & `IND-17`)**

1. Every smallholder farm boundary registered by an extension worker or cooperative MUST be encoded as a closed GeoJSON `Polygon` (WGS84 `EPSG:4326`) with minimum 4 vertex coordinates, captured offline via `KioskBase` (`kbd_` ULID) and linked to a salted hash of the farmer''s `NIN` and `LandGuard` 3×3m grid code.  
2. **Anti-Overlap Cadastral Check:** Before issuing an input-financing or warehouse-receipt credential, the state/LGA node MUST verify zero polygon intersection against conflicting claims or active High Court / Customary Court *lis pendens* encumbrances.  
3. **Negotiable Electronic Warehouse Receipt (`e-WR`):** Certified commodities warehouses (e.g., AFEX, NCX, or state grain silos) seal Assay & Weight certificates with a `SureEvidence` (`s84_` ULID) hardware key so commercial banks can perfect collateral liens programmatically under CBN/SEC rules.

---
', 'specs/openapi/v2026/', 'https://nigeriastack.org/schemas/v2026/', '5ee35781809058a5ca9bc0c2c61fa5fa89d05137e00cdc3b2d268c8f3e50beb5', '2026-11-16T00:00:00Z');
INSERT INTO ngstack_global_search_fts (entity_type, entity_id, canonical_url, title_civic, body_searchable, statutory_tags) VALUES ('RFC', 'NS-RFC-012', '/rfcs/NS-RFC-012', 'AgriTrust Smallholder Farm Geopolygon & Negotiable Warehouse Receipt Standard', '3\. NS-RFC-012: `AgriTrust` Smallholder Farm Geopolygon & Negotiable Warehouse Receipt Standard**', 'Land Use Act 1978 SEC Rules');
INSERT OR REPLACE INTO normative_rfcs (rfc_id, slug, title, working_group, status, hourglass_layer, statutory_anchors_json, summary_civic, full_markdown_body, openapi_contract_path, json_schema_uri, sha256_digest, updated_at_utc) VALUES ('NS-RFC-013', 'ns-rfc-013-indigenous-language-legal-ast', 'LawTree AST (StatuteProof) Bi-Temporal Statutory Graph & 5-Locale Indigenous Legal Lexicon', 'WG-02', 'RATIFIED_NORMATIVE', 'Layer 3', '["1999 CFRN s. 36(3)-(4)", "Evidence Act 2011 s. 106"]', '4\. NS-RFC-013: `LawTree AST` (`StatuteProof`) Bi-Temporal Statutory Graph & 5-Locale Indigenous Legal Lexicon**', '# **4\. NS-RFC-013: `LawTree AST` (`StatuteProof`) Bi-Temporal Statutory Graph & 5-Locale Indigenous Legal Lexicon**

* **Status:** CANDIDATE STANDARD (Stage 3\)  
* **Working Group:** WG-02 (SureEvidence Cryptographic Trust, Legal ASTs & Admissibility)  
* **Namespace URI:** `urn:ngstack:lawtree:v2026`  
* **Statutory Anchor:** Laws of the Federation of Nigeria (LFN); Laws of the 36 States; 1999 Constitution s. 36(3)–(4); Evidence Act 2011 s. 106; OASIS LegalDocML (Akoma Ntoso 3.0).  
* **Target Gap Mechanisms:** `MECH-03` (Semantic Gap), `MECH-05` (Provenance Gap), `MECH-08` (Static-PDF Law Gap)

## **4.1 Deterministic Section URN Grammar & Bi-Temporal Versioning (`IND-21` & `IND-31`)**

1. Every Act of the National Assembly, State Law, Subsidiary Regulation (CBN/NDPC/SEC/NRS), and Court Practice Direction MUST be compiled into a bi-temporal `LawTree AST` node addressed by the canonical URN:  
   `urn:lex:ng:{jurisdiction}:act:{year}-{number}@{enacted_or_amended_date}#sec_{section_id}`  
2. Every AST node MUST carry both `valid_period` (statutory commencement to repeal/amendment date) and `sys_period` (gazette ingestion timestamp) plus a `SureEvidence` SHA-256 digest of the official Gazette PDF page and `[x0, y0, x1, y1]` normalized bounding box.

## **4.2 5-Locale Indigenous Legal & Civic Semantic Gate (`IND-27`)**

* Translations of statutory notices, court dispositions, `ClearAm` consent prompts, and 774-LGA service instructions across **`en-NG` (Nigerian English)**, **`ha-NG` (Hausa)**, **`yo-NG` (Yoruba)**, **`ig-NG` (Igbo)**, and **`pcm-NG` (Nigerian Pidgin)** MUST embed an explicit `reviewState` enum:  
  `"DRAFT_UNPUBLISHED"` \| `"LINGUISTIC_REVIEW_PASSED"` \| `"LEGAL_SEMANTIC_REVIEW_APPROVED"`.  
* **Hard Guardrail:** Any locale string with `reviewState != "LEGAL_SEMANTIC_REVIEW_APPROVED"` MUST NOT render as authoritative legal or consent guidance without a visible machine-translation disclaimer banner.

---
', 'specs/openapi/v2026/', 'https://nigeriastack.org/schemas/v2026/', 'ee98103e18d166c4dad873ae31d3375daf2f57563aee6d20fcb5c5c44d58c0ef', '2026-11-16T00:00:00Z');
INSERT INTO ngstack_global_search_fts (entity_type, entity_id, canonical_url, title_civic, body_searchable, statutory_tags) VALUES ('RFC', 'NS-RFC-013', '/rfcs/NS-RFC-013', 'LawTree AST (StatuteProof) Bi-Temporal Statutory Graph & 5-Locale Indigenous Legal Lexicon', '4\. NS-RFC-013: `LawTree AST` (`StatuteProof`) Bi-Temporal Statutory Graph & 5-Locale Indigenous Legal Lexicon**', '1999 CFRN s. 36(3)-(4) Evidence Act 2011 s. 106');
INSERT OR REPLACE INTO normative_rfcs (rfc_id, slug, title, working_group, status, hourglass_layer, statutory_anchors_json, summary_civic, full_markdown_body, openapi_contract_path, json_schema_uri, sha256_digest, updated_at_utc) VALUES ('NS-RFC-014', 'ns-rfc-014-lga-774-municipal-governance-stack', 'LgaGovernanceStack — 774 Constitutional LGAs & 6 FCT Area Councils Municipal Specification', 'WG-05', 'RATIFIED_NORMATIVE', 'Layer 5', '["1999 CFRN s. 7(1) & Fourth Schedule", "SC/CV/343/2024"]', '5\. NS-RFC-014: `LgaGovernanceStack` — 774 Constitutional Local Government Areas & 6 FCT Area Councils Municipal Specification**', '# **5\. NS-RFC-014: `LgaGovernanceStack` — 774 Constitutional Local Government Areas & 6 FCT Area Councils Municipal Specification**

* **Status:** CANDIDATE STANDARD (Stage 3\)  
* **Working Group:** WG-05 (in joint session with WG-03)  
* **Namespace URI:** `urn:ngstack:lga-stack:v2026`  
* **Statutory Anchor:** Section 7(1) & Fourth Schedule, 1999 Constitution of the Federal Republic of Nigeria (as amended); Supreme Court Judgment *AG Federation v. AG Abia State & 35 Ors (SC/CV/343/2024, July 11, 2024\)*; Birth, Death, Etc. (Compulsory Registration) Act; Evidence Act 2011 s. 84\.  
* **Target Gap Mechanisms:** `MECH-02` (Grassroots Coverage Gap), `MECH-05` (Forged Paper Certificates), `MECH-06` (Rural Power/2G Drops), `MECH-07` (Cash-Touting / *Agbero* IGR Leakage)

## **5.1 Normative Architecture for the 14 Municipal Service Modules (`LGA-01` to `LGA-14`)**

Every implementation of `LgaGovernanceStack` across Nigeria''s 774 LGAs MUST support offline-first `KioskBase` (**\< 35 KB** PWA / POS / USSD) operation across all 14 standardized Fourth-Schedule modules:

* **Citizen & Commercial Licensing Modules:** `LGA-01` (`CouncilComplain`), `LGA-02` (`BuildClear`), `LGA-03` (`WashConnect`), `LGA-04` (`ShopPermit`), `LGA-05` (`VitalProof`), `LGA-06` (`IndigeneProof`), `LGA-07` (`SafetyNOC`), `LGA-08` (`WardWorks`), `LGA-11` (`WardPHC`), `LGA-13` (`CustomaryDocket`), and `LGA-14` (`StreetGrid`).  
* **Direct Revenue & Fiscal Modules:** `LGA-09` (`TenementRate`), `LGA-10` (`MarketCollect`), and `LGA-12` (`CouncilLedger`).

## **5.2 Supreme Court `SC/CV/343/2024` Direct LGA Treasury Invariance**

1. **Zero State Joint Account (`SJLGA`) or Vendor Diversion:** All demand-based field collections (`LGA-10` `MarketCollect` across motor parks, open markets, abattoirs, and loading bays) and property rates (`LGA-09` `TenementRate`) MUST enforce `NS-RFC-009` (`SplitDirect`) with `platform_escrow_amount_kobo == 0` and `state_intermediary_escrow_kobo == 0`.  
2. **100% Direct LGA Treasury Settlement:** Statutory principal sums route directly into the respective Local Government Council''s verified CBN/Commercial Bank Treasury Account.  
3. **Anti-Forgery `IndigeneProof` & `VitalProof` Seals:** Every LGA Indigene/Residency Attestation (`LGA-06`) and Birth/Death/Marriage record (`LGA-05`) MUST be signed by the authorized LGA Registrar/Chairman FIDO2 Ed25519 key (`SureEvidence` `s84_` ULID), eliminating forged paper indigene letters nationwide.

## **5.3 Normative 14-Module Playbook Persona, Pain-Point & State-Machine Matrix (LGA-01 to LGA-14)**

* **LGA-01 (`CouncilComplain` —** `/protocols/lga-governance-stack/lga-01-council-complain`**):** Fourth Schedule Para 1(b), (e), (h) (Roads, drains, refuse, clinic upkeep). Targets Cluster 6 (Citizens/Traders) & Cluster 3 (LGA Chairmen) (`MECH-02`, `MECH-06`). State Machine: `FILED_OFFLINE` \-\> `ASSIGNED_WARD_OFFICER` \-\> `GEO_PHOTO_ATTESTED` (`SureEvidence` `s84_` hash) \-\> `CITIZEN_CLOSED`.  
* **LGA-02 (`BuildClear` —** `/protocols/lga-governance-stack/lga-02-build-clear`**):** Fourth Schedule Para 1(f) & 2(d) (Building setback & stall erection permits). Targets Cluster 6 (Property Owners) & Cluster 3 (Town Planners) (`MECH-03`, `MECH-05`). Requires 3x3m `LandGuard` parcel grid code \+ Inspector FIDO2 Ed25519 `SureEvidence` QR permit.  
* **LGA-03 (`WashConnect` —** `/protocols/lga-governance-stack/lga-03-wash-connect`**):** Fourth Schedule Para 1(h) (Borehole O\&M, water connections & faecal sludge management). Targets Cluster 6 (Households) & Cluster 3 (WASH Committees) (`MECH-04`, `MECH-06`). `SplitDirect` holds tariff until treatment plant scans truck''s `SureEvidence` discharge QR token.  
* **LGA-04 (`ShopPermit` —** `/protocols/lga-governance-stack/lga-04-shop-permit`**):** Fourth Schedule Para 1(e), (i), (k) (Markets, lock-up shops, kiosks, bakeries, eateries, liquor & signage). Targets Cluster 6 (MSMEs) & Cluster 4 (Microfinance Banks) (`MECH-05`, `MECH-07`). Issues annual `SureEvidence` (`s84_` ULID) QR Shop Sticker verifiable offline.  
* **LGA-05 (`VitalProof` —** `/protocols/lga-governance-stack/lga-05-vital-proof`**):** Fourth Schedule Para 1(i) (Births, deaths, burials, customary/LGA marriages). Targets Cluster 6 (Families) & Cluster 1 (Registrars) (`MECH-05`, `MECH-06`). Offline `KioskBase` (`kbd_` ULID) capture federated with NPC `NIN` bridge \+ s. 84 QR seal.  
* **LGA-06 (`IndigeneProof` —** `/protocols/lga-governance-stack/lga-06-indigene-proof`**):** Federal Character & LGA Origin/Residency Attestation Mandate. Targets Cluster 6 (Applicants), Cluster 3 (LGA Secretaries) & Cluster 4 (Employers/Military/Universities) (`MECH-02`, `MECH-05`). Requires `ClearAm` (`LGA-INDIGENE-AND-VITAL-ATTESTATION`) \+ FIDO2 Ed25519 `SureEvidence` seal.  
* **LGA-07 (`SafetyNOC` —** `/protocols/lga-governance-stack/lga-07-safety-noc`**):** Fourth Schedule Para 1(e) & (h) (Abattoir hygiene & market fire-safety NOC). Targets Cluster 6 (Market Associations) & Cluster 3 (Environmental Health Officers) (`MECH-05`). Geo-stamped `SureEvidence` inspection certificate.  
* **LGA-08 (`WardWorks` —** `/protocols/lga-governance-stack/lga-08-ward-works`**):** Fourth Schedule Para 1(f) (Feeder roads, drains, street lighting & ward micro-projects). Targets Cluster 3 (LGA Councils/Auditors) & Cluster 7 (Civic Researchers) (`MECH-05`, `MECH-07`). Links OCDS contract ID to geo-fenced before/after `SureEvidence` photo hashes before `SplitDirect` milestone release.  
* **LGA-09 (`TenementRate` —** `/protocols/lga-governance-stack/lga-09-tenement-rate`**):** Fourth Schedule Para 1(j) (Assessment of privately owned houses/tenements). Targets Cluster 3 (LGA Revenue Officers) & Cluster 6 (Landlords) (`MECH-02`, `MECH-07`). Bound to `LandGuard` parcel polygon and `SplitDirect` (`platformEscrowAmountKobo == 0`) direct LGA Treasury settlement.  
* **LGA-10 (`MarketCollect` —** `/protocols/lga-governance-stack/lga-10-market-collect`**):** Fourth Schedule Para 1(e) (Motor parks, open markets, loading bays & wheelbarrows). Targets Cluster 6 (Drivers/Traders) & Cluster 3 (LGA Treasurers) (`MECH-05`, `MECH-06`, `MECH-07`). Offline `KioskBase` POS/USSD/QR ticket \+ `SplitDirect` 100% direct remittance to LGA Treasury under `SC/CV/343/2024` (`stateIntermediaryEscrowKobo == 0`).  
* **LGA-11 (`WardPHC` —** `/protocols/lga-governance-stack/lga-11-ward-phc`**):** Fourth Schedule Para 2(c) (Primary Health Care, immunization & SMC campaigns). Targets Cluster 6 (Mothers/Infants) & Cluster 3 (PHC Officers) (`MECH-02`, `MECH-06`). Offline `KioskBase` ward enumeration \+ `NDHX` HL7 FHIR immunization log (scaling the Kebbi State 21-LGA baseline).  
* **LGA-12 (`CouncilLedger` —** `/protocols/lga-governance-stack/lga-12-council-ledger`**):** Section 7(1), Section 162 CFRN & `SC/CV/343/2024` Direct FAAC \+ IGR Fiscal Accountability. Targets Cluster 3 (Auditors/NFIU) & Cluster 7 (Civic Monitors) (`MECH-03`, `MECH-05`). Real-time ward IGR \+ FAAC ledger with WORM SHA-256 receipts.  
* **LGA-13 (`CustomaryDocket` —** `/protocols/lga-governance-stack/lga-13-customary-docket`**):** Customary, Area & District Courts at LGA level. Targets Cluster 1 (Court Clerks), Cluster 2 (Counsel) & Cluster 6 (Litigants) (`MECH-05`, `MECH-06`). Offline `KioskBase` intake with `INTERNAL_RESTRICTED_NDPA` kernel lock on family/minor files \+ s. 84 CTCs.  
* **LGA-14 (`StreetGrid` —** `/protocols/lga-governance-stack/lga-14-street-grid`**):** Fourth Schedule Para 1(g) (Street naming & house numbering). Targets Cluster 6 (Residents/MSMEs) & Cluster 4 (Banks/Couriers) (`MECH-02`, `MECH-06`). Offline-computable 3x3m `StreetGrid` code bound to LGA street gazettes.

## **5.3 Normative Specification & Playbook Audience/Pain-Point Crosswalk for All 14 Municipal Service Modules (LGA-01 to LGA-14)**

**LGA-01 (`CouncilComplain` —** `/protocols/lga-governance-stack/lga-01-council-complain`**):** Fourth Schedule Para 1(b), (e), (h): Public roads, drains, refuse disposal, and clinic upkeep. Solves `MECH-02` & `MECH-06` for Cluster 6 (Citizens/Traders) & Cluster 3 (LGA Chairmen). State Machine: `FILED_OFFLINE` \-\> `ASSIGNED_WARD_OFFICER` \-\> `GEO_PHOTO_ATTESTED` (`SureEvidence` `s84_` hash) \-\> `CITIZEN_CLOSED`.  
**LGA-02 (`BuildClear` —** `/protocols/lga-governance-stack/lga-02-build-clear`**):** Fourth Schedule Para 1(f) & 2(d): Building setback and local commercial stall permits. Solves `MECH-03` & `MECH-05` for Cluster 6 (Property Owners) & Cluster 3 (Town Planners) using 3×3m `LandGuard` grid coordinates and Inspector FIDO2 Ed25519 `SureEvidence` QR permits.  
**LGA-03 (`WashConnect` —** `/protocols/lga-governance-stack/lga-03-wash-connect`**):** Fourth Schedule Para 1(h): Rural borehole O\&M, water connections, and faecal sludge management (FSM). Solves `MECH-04` & `MECH-06` for Cluster 6 (Households) & Cluster 3 (WASH Committees) using `SplitDirect` conditional tariff release upon treatment-plant `SureEvidence` QR scan.  
**LGA-04 (`ShopPermit` —** `/protocols/lga-governance-stack/lga-04-shop-permit`**):** Fourth Schedule Para 1(e), (i), (k): Market stall, lock-up shop, kiosk, bakery, liquor, and signage licensing. Solves `MECH-05` & `MECH-07` for Cluster 6 (MSMEs) & Cluster 4 (Microfinance Banks) via annual `SureEvidence` (`s84_` ULID) laminated QR stickers verifiable offline.  
**LGA-05 (`VitalProof` —** `/protocols/lga-governance-stack/lga-05-vital-proof`**):** Fourth Schedule Para 1(i): Birth, death, burial, and customary/local government marriage registration. Solves `MECH-05` & `MECH-06` for Cluster 6 (Families) & Cluster 1 (Registrars) via offline `KioskBase` (`kbd_` ULID) capture, NPC NIN bridge federation, and s. 84 QR certificates.  
**LGA-06 (`IndigeneProof` —** `/protocols/lga-governance-stack/lga-06-indigene-proof`**):** Nigerian Constitutional Federal Character & LGA Origin/Residency Attestation. Solves `MECH-02` & `MECH-05` for Cluster 6 (Applicants), Cluster 3 (LGA Secretaries) & Cluster 4 (Employers/Military/Universities) via `ClearAm` (`LGA-INDIGENE-AND-VITAL-ATTESTATION`) \+ LGA Secretary/Chairman FIDO2 Ed25519 `SureEvidence` QR seal.  
**LGA-07 (`SafetyNOC` —** `/protocols/lga-governance-stack/lga-07-safety-noc`**):** Fourth Schedule Para 1(e) & (h): Abattoir hygiene and market fire-safety No-Objection Certificates. Solves `MECH-05` for Cluster 6 (Market Associations) & Cluster 3 (Environmental Health Officers).  
**LGA-08 (`WardWorks` —** `/protocols/lga-governance-stack/lga-08-ward-works`**):** Fourth Schedule Para 1(f): Feeder roads, culverts, and ward micro-projects. Solves `MECH-05` & `MECH-07` for Cluster 3 (LGA Auditors) & Cluster 7 (Civic Researchers) by binding OCDS contract IDs to geo-fenced before/after `SureEvidence` photo hashes prior to `SplitDirect` milestone payout.  
**LGA-09 (`TenementRate` —** `/protocols/lga-governance-stack/lga-09-tenement-rate`**):** Fourth Schedule Para 1(j): Privately owned tenement rate assessment and collection. Solves `MECH-02` & `MECH-07` for Cluster 3 (LGA Revenue Officers) & Cluster 6 (Landlords) using `LandGuard` parcel polygons and `SplitDirect` (`platform_escrow_amount_kobo == 0`) direct LGA Treasury settlement.  
**LGA-10 (`MarketCollect` —** `/protocols/lga-governance-stack/lga-10-market-collect`**):** Fourth Schedule Para 1(e): Daily demand-based fee collection in motor parks, open markets, abattoirs, and loading bays. Solves `MECH-05`, `MECH-06`, & `MECH-07` (eradicating *agbero* cash touting) for Cluster 6 (Drivers/Traders) & Cluster 3 (LGA Treasurers) via offline `KioskBase` POS/USSD/QR tickets and 100% direct LGA CBN/Commercial Bank settlement under `SC/CV/343/2024` (`stateIntermediaryEscrowKobo == 0`).  
**LGA-11 (`WardPHC` —** `/protocols/lga-governance-stack/lga-11-ward-phc`**):** Fourth Schedule Para 2(c): Ward Primary Health Care (PHC) immunization and Seasonal Malaria Chemoprevention (SMC) micro-planning. Solves `MECH-02` & `MECH-06` for Cluster 6 (Mothers/Infants) & Cluster 3 (PHC Officers) via offline `KioskBase` enumeration and `NDHX` HL7 FHIR sync (scaling the verified Kebbi State 21-LGA baseline).  
**LGA-12 (`CouncilLedger` —** `/protocols/lga-governance-stack/lga-12-council-ledger`**):** Section 7(1), Section 162 CFRN & Supreme Court `SC/CV/343/2024`: Direct FAAC \+ ward IGR fiscal transparency ledger. Solves `MECH-03` & `MECH-05` for Cluster 3 (Auditors/NFIU) & Cluster 7 (Civic Monitors).  
**LGA-13 (`CustomaryDocket` —** `/protocols/lga-governance-stack/lga-13-customary-docket`**):** Customary, Area, and District Courts at the LGA level. Solves `MECH-05` & `MECH-06` for Cluster 1 (Court Clerks), Cluster 2 (Counsel), & Cluster 6 (Litigants) via offline `KioskBase` intake, PostgreSQL 17 `FORCE RLS` (`INTERNAL_RESTRICTED_NDPA` lock on family/minor files), and s. 84 QR-sealed CTCs for appellate transmission.  
**LGA-14 (`StreetGrid` —** `/protocols/lga-governance-stack/lga-14-street-grid`**):** Fourth Schedule Para 1(g): Street naming, house numbering, and rural ward digital addressing. Solves `MECH-02` & `MECH-06` for Cluster 6 (Residents) & Cluster 4 (Banks/Couriers) via offline-computable alphanumeric grid codes linked to `LandGuard` 3×3m coordinates.

