INSERT OR REPLACE INTO lga_service_modules_14 VALUES ('LGA-01', '/protocols/lga-governance-stack/lga-01-council-complain', 'CouncilComplain', 'CouncilComplain', 'Fourth Schedule Para 1(b), (e), (h): Public roads, drains, refuse disposal, and primary facility upkeep.', '["CLUSTER_6_CITIZENS_TRADERS", "CLUSTER_3_LGA_CHAIRMEN_DIRECTORS"]', '["MECH-02", "MECH-06"]', 1, 1, 'https://nigeriastack.org/schemas/v2026/LgaGovernanceServiceEnvelope.schema.json');
INSERT INTO ngstack_global_search_fts VALUES ('LGA_MODULE', 'LGA-01', '/protocols/lga-governance-stack/lga-01-council-complain', 'LGA-01: CouncilComplain', 'Citizens lack an offline channel to report burst pipes, blocked drainages, or clinic closures; Chairmen cannot verify if contractors fixed the fault.', 'Fourth Schedule Para 1(b), (e), (h): Public roads, drains, refuse disposal, and primary facility upkeep.');
INSERT OR REPLACE INTO lga_service_modules_14 VALUES ('LGA-02', '/protocols/lga-governance-stack/lga-02-build-clear', 'BuildClear', 'BuildClear', 'Fourth Schedule Para 1(f) & 2(d): Local building setback, culvert, and commercial stall erection approval.', '["CLUSTER_6_PROPERTY_OWNERS", "CLUSTER_3_TOWN_PLANNERS"]', '["MECH-03", "MECH-05"]', 1, 1, 'https://nigeriastack.org/schemas/v2026/LgaGovernanceServiceEnvelope.schema.json');
INSERT INTO ngstack_global_search_fts VALUES ('LGA_MODULE', 'LGA-02', '/protocols/lga-governance-stack/lga-02-build-clear', 'LGA-02: BuildClear', 'Eliminates extortion by unverified field inspectors and coordinates local setback permits with State GIS parcels.', 'Fourth Schedule Para 1(f) & 2(d): Local building setback, culvert, and commercial stall erection approval.');
INSERT OR REPLACE INTO lga_service_modules_14 VALUES ('LGA-03', '/protocols/lga-governance-stack/lga-03-wash-connect', 'WashConnect', 'WashConnect', 'Fourth Schedule Para 1(h): Public conveniences, sewage, faecal sludge management (FSM), and rural borehole O&M.', '["CLUSTER_6_HOUSEHOLDS", "CLUSTER_3_WASH_COMMITTEES"]', '["MECH-04", "MECH-06"]', 1, 1, 'https://nigeriastack.org/schemas/v2026/LgaGovernanceServiceEnvelope.schema.json');
INSERT INTO ngstack_global_search_fts VALUES ('LGA_MODULE', 'LGA-03', '/protocols/lga-governance-stack/lga-03-wash-connect', 'LGA-03: WashConnect', 'Prevents rural borehole breakdown from uncollected O&M tariffs and stops illegal sewage dumping by un-tracked desludging trucks.', 'Fourth Schedule Para 1(h): Public conveniences, sewage, faecal sludge management (FSM), and rural borehole O&M.');
INSERT OR REPLACE INTO lga_service_modules_14 VALUES ('LGA-04', '/protocols/lga-governance-stack/lga-04-shop-permit', 'ShopPermit', 'ShopPermit', 'Fourth Schedule Para 1(e), (i), (k): Licensing of markets, lock-up shops, kiosks, bakeries, eateries, liquor & outdoor signage.', '["CLUSTER_6_MSMES_TRADERS", "CLUSTER_4_MICROFINANCE_BANKS"]', '["MECH-05", "MECH-07"]', 1, 1, 'https://nigeriastack.org/schemas/v2026/LgaGovernanceServiceEnvelope.schema.json');
INSERT INTO ngstack_global_search_fts VALUES ('LGA_MODULE', 'LGA-04', '/protocols/lga-governance-stack/lga-04-shop-permit', 'LGA-04: ShopPermit', 'Eliminates forged paper demand notices and multiple taxation by touts; provides verifiable shop credentials for MSME micro-credit.', 'Fourth Schedule Para 1(e), (i), (k): Licensing of markets, lock-up shops, kiosks, bakeries, eateries, liquor & outdoor signage.');
INSERT OR REPLACE INTO lga_service_modules_14 VALUES ('LGA-05', '/protocols/lga-governance-stack/lga-05-vital-proof', 'VitalProof', 'VitalProof', 'Fourth Schedule Para 1(i): Registration of all births, deaths, burials, and customary/local government marriages; NPC Act.', '["CLUSTER_6_CITIZENS_FAMILIES", "CLUSTER_1_REGISTRARS"]', '["MECH-05", "MECH-06"]', 1, 1, 'https://nigeriastack.org/schemas/v2026/LgaGovernanceServiceEnvelope.schema.json');
INSERT INTO ngstack_global_search_fts VALUES ('LGA_MODULE', 'LGA-05', '/protocols/lga-governance-stack/lga-05-vital-proof', 'LGA-05: VitalProof', 'Prevents unregistered rural births/deaths during network drops and stops forged marriage/death certificates in probate and visa filings.', 'Fourth Schedule Para 1(i): Registration of all births, deaths, burials, and customary/local government marriages; NPC Act.');
INSERT OR REPLACE INTO lga_service_modules_14 VALUES ('LGA-06', '/protocols/lga-governance-stack/lga-06-indigene-proof', 'IndigeneProof', 'IndigeneProof', 'Nigerian Constitutional Federal Character & LGA Origin/Residency Attestation Mandate.', '["CLUSTER_6_YOUTH_APPLICANTS", "CLUSTER_3_LGA_SECRETARIES", "CLUSTER_4_EMPLOYERS_INSTITUTIONS"]', '["MECH-02", "MECH-05", "MECH-07"]', 1, 1, 'https://nigeriastack.org/schemas/v2026/LgaGovernanceServiceEnvelope.schema.json');
INSERT INTO ngstack_global_search_fts VALUES ('LGA_MODULE', 'LGA-06', '/protocols/lga-governance-stack/lga-06-indigene-proof', 'LGA-06: IndigeneProof', 'Eliminates forged paper LGA Indigene letters, multi-week ward endorsement delays, and travel burdens via a 72-hour SLA and USSD community vouching.', 'Nigerian Constitutional Federal Character & LGA Origin/Residency Attestation Mandate.');
INSERT OR REPLACE INTO lga_service_modules_14 VALUES ('LGA-07', '/protocols/lga-governance-stack/lga-07-safety-noc', 'SafetyNOC', 'SafetyNOC', 'Fourth Schedule Para 1(e) & (h): Slaughter slabs, abattoir hygiene, and market fire-safety clearances.', '["CLUSTER_6_MARKET_ASSOCIATIONS", "CLUSTER_3_ENV_HEALTH_OFFICERS"]', '["MECH-05"]', 1, 1, 'https://nigeriastack.org/schemas/v2026/LgaGovernanceServiceEnvelope.schema.json');
INSERT INTO ngstack_global_search_fts VALUES ('LGA_MODULE', 'LGA-07', '/protocols/lga-governance-stack/lga-07-safety-noc', 'LGA-07: SafetyNOC', 'Replaces fake paper environmental and fire clearance letters with geo-stamped inspection photos and time-bounded Section 84 QR certificates.', 'Fourth Schedule Para 1(e) & (h): Slaughter slabs, abattoir hygiene, and market fire-safety clearances.');
INSERT OR REPLACE INTO lga_service_modules_14 VALUES ('LGA-08', '/protocols/lga-governance-stack/lga-08-ward-works', 'WardWorks', 'WardWorks', 'Fourth Schedule Para 1(f): Construction and maintenance of feeder roads, drains, street lighting, and ward micro-projects.', '["CLUSTER_3_LGA_COUNCILS_AUDITORS", "CLUSTER_7_CIVIC_RESEARCHERS"]', '["MECH-05", "MECH-07"]', 1, 1, 'https://nigeriastack.org/schemas/v2026/LgaGovernanceServiceEnvelope.schema.json');
INSERT INTO ngstack_global_search_fts VALUES ('LGA_MODULE', 'LGA-08', '/protocols/lga-governance-stack/lga-08-ward-works', 'LGA-08: WardWorks', 'Blocks ghost ward projects and payments for unexecuted feeder-road grading by requiring geo-fenced before/after SureEvidence photo hashes before milestone release.', 'Fourth Schedule Para 1(f): Construction and maintenance of feeder roads, drains, street lighting, and ward micro-projects.');
INSERT OR REPLACE INTO lga_service_modules_14 VALUES ('LGA-09', '/protocols/lga-governance-stack/lga-09-tenement-rate', 'TenementRate', 'TenementRate', 'Fourth Schedule Para 1(j) & Land Use Act 1978 s. 6: Assessment of privately owned houses/tenements and Customary Rights of Occupancy.', '["CLUSTER_3_LGA_REVENUE_OFFICERS", "CLUSTER_6_LANDLORDS_OCCUPIERS"]', '["MECH-02", "MECH-05", "MECH-07"]', 1, 1, 'https://nigeriastack.org/schemas/v2026/LgaGovernanceServiceEnvelope.schema.json');
INSERT INTO ngstack_global_search_fts VALUES ('LGA_MODULE', 'LGA-09', '/protocols/lga-governance-stack/lga-09-tenement-rate', 'LGA-09: TenementRate', 'Eliminates arbitrary manual assessments, cash diversion, and double-allocation of Customary C of O parcels during active Customary Court disputes.', 'Fourth Schedule Para 1(j) & Land Use Act 1978 s. 6: Assessment of privately owned houses/tenements and Customary Rights of Occupancy.');
INSERT OR REPLACE INTO lga_service_modules_14 VALUES ('LGA-10', '/protocols/lga-governance-stack/lga-10-market-collect', 'MarketCollect', 'MarketCollect', 'Fourth Schedule Para 1(e) & SC/CV/343/2024: Collection of daily fees in markets, motor parks, loading bays, and inter-LGA haulage corridors.', '["CLUSTER_6_DRIVERS_MARKET_WOMEN", "CLUSTER_3_LGA_TREASURERS"]', '["MECH-05", "MECH-06", "MECH-07"]', 1, 1, 'https://nigeriastack.org/schemas/v2026/LgaGovernanceServiceEnvelope.schema.json');
INSERT INTO ngstack_global_search_fts VALUES ('LGA_MODULE', 'LGA-10', '/protocols/lga-governance-stack/lga-10-market-collect', 'LGA-10: MarketCollect', 'Eradicates cash touting (agbero leakage), fake paper tickets, and inter-LGA commercial vehicle double-taxation via offline POS/USSD tickets and a verifiable Inter-LGA Corridor Pass.', 'Fourth Schedule Para 1(e) & SC/CV/343/2024: Collection of daily fees in markets, motor parks, loading bays, and inter-LGA haulage corridors.');
INSERT OR REPLACE INTO lga_service_modules_14 VALUES ('LGA-11', '/protocols/lga-governance-stack/lga-11-ward-phc', 'WardPHC', 'WardPHC', 'Fourth Schedule Para 2(c): Provision and maintenance of Primary Health Care (PHC), immunization, and Seasonal Malaria Chemoprevention (SMC).', '["CLUSTER_6_MOTHERS_INFANTS", "CLUSTER_3_PHC_HEALTH_WORKERS"]', '["MECH-02", "MECH-06"]', 1, 1, 'https://nigeriastack.org/schemas/v2026/LgaGovernanceServiceEnvelope.schema.json');
INSERT INTO ngstack_global_search_fts VALUES ('LGA_MODULE', 'LGA-11', '/protocols/lga-governance-stack/lga-11-ward-phc', 'LGA-11: WardPHC', 'Replaces lost paper tally sheets and prevents vaccine/malaria commodity stockouts in rural wards (scaling the verified Kebbi State 21-LGA baseline nationwide).', 'Fourth Schedule Para 2(c): Provision and maintenance of Primary Health Care (PHC), immunization, and Seasonal Malaria Chemoprevention (SMC).');
INSERT OR REPLACE INTO lga_service_modules_14 VALUES ('LGA-12', '/protocols/lga-governance-stack/lga-12-council-ledger', 'CouncilLedger', 'CouncilLedger', 'Section 7(1), Section 162 CFRN & Supreme Court SC/CV/343/2024 Direct FAAC + IGR Fiscal Accountability.', '["CLUSTER_3_AUDITORS_NFIU", "CLUSTER_7_CIVIC_MONITORS"]', '["MECH-03", "MECH-05"]', 1, 1, 'https://nigeriastack.org/schemas/v2026/LgaGovernanceServiceEnvelope.schema.json');
INSERT INTO ngstack_global_search_fts VALUES ('LGA_MODULE', 'LGA-12', '/protocols/lga-governance-stack/lga-12-council-ledger', 'LGA-12: CouncilLedger', 'Provides real-time ward-level transparency over direct FAAC allocations and SplitDirect local IGR collections with daily signed SHA-256 Merkle roots.', 'Section 7(1), Section 162 CFRN & Supreme Court SC/CV/343/2024 Direct FAAC + IGR Fiscal Accountability.');
INSERT OR REPLACE INTO lga_service_modules_14 VALUES ('LGA-13', '/protocols/lga-governance-stack/lga-13-customary-docket', 'CustomaryDocket', 'CustomaryDocket', 'Customary, Area, and District Courts operating at the LGA level across the 36 States + FCT; NDPA 2023 ss. 30–31.', '["CLUSTER_1_COURT_CLERKS_JUDGES", "CLUSTER_2_LEGAL_PRACTITIONERS", "CLUSTER_6_LITIGANTS"]', '["MECH-02", "MECH-05", "MECH-06"]', 1, 1, 'https://nigeriastack.org/schemas/v2026/LgaGovernanceServiceEnvelope.schema.json');
INSERT INTO ngstack_global_search_fts VALUES ('LGA_MODULE', 'LGA-13', '/protocols/lga-governance-stack/lga-13-customary-docket', 'LGA-13: CustomaryDocket', 'Digitizes paper-bound Area/Customary courts offline, preserves appellate records to State High Courts, and locks matrimonial/minor files inside INTERNAL_RESTRICTED_NDPA.', 'Customary, Area, and District Courts operating at the LGA level across the 36 States + FCT; NDPA 2023 ss. 30–31.');
INSERT OR REPLACE INTO lga_service_modules_14 VALUES ('LGA-14', '/protocols/lga-governance-stack/lga-14-street-grid', 'StreetGrid', 'StreetGrid', 'Fourth Schedule Para 1(g): Naming of roads and streets and the numbering of houses.', '["CLUSTER_6_RESIDENTS_MSMES", "CLUSTER_4_BANKS_COURIERS"]', '["MECH-02", "MECH-06"]', 1, 1, 'https://nigeriastack.org/schemas/v2026/LgaGovernanceServiceEnvelope.schema.json');
INSERT INTO ngstack_global_search_fts VALUES ('LGA_MODULE', 'LGA-14', '/protocols/lga-governance-stack/lga-14-street-grid', 'LGA-14: StreetGrid', 'Assigns every rural and peri-urban house/shop an offline-computable 3x3m alphanumeric StreetGrid address linked to official LGA street-naming gazettes.', 'Fourth Schedule Para 1(g): Naming of roads and streets and the numbering of houses.');
INSERT OR REPLACE INTO daily_merkle_audit_roots VALUES ('2026-11-16', '8f4b2e91c0d74a15b63e89f123456789abcdef0123456789abcdef0123456789', 'v2026.6.5', 1, '["did:web:nigeriastack.org#wg02-sure-evidence-root-2026"]', '2026-11-16T00:00:00Z');
INSERT INTO ngstack_global_search_fts VALUES ('FAQ', 'NS-FAQ-01', '/governance#' || 'NS-FAQ-01', 'Is Nigeria Stack a government agency portal, a payment processor, or a commercial API store?', 'Verify the institutional role and governance rules of nigeriastack.org before adopting its technical specifications. Under the Institutional Positioning Charter, nigeriastack.org is an independent public-domain specification commons aligned with federal technology standards and national interoperability guidelines.', 'NS-RFC-001');
INSERT INTO ngstack_global_search_fts VALUES ('FAQ', 'NS-FAQ-02', '/governance#' || 'NS-FAQ-02', 'Do government agencies like NIMC, CAC, NIBSS, NRS, or State Land Registries have to hand over their databases to use Nigeria Stack?', 'Connect statutory government registries to Nigeria Stack using secure, outward-facing verification tools. Statutory institutions established under federal or state laws retain 100% legal ownership and control over their official master databases.', 'NS-RFC-001 NS-RFC-005 NS-RFC-006');
INSERT INTO ngstack_global_search_fts VALUES ('FAQ', 'NS-FAQ-03', '/governance#' || 'NS-FAQ-03', 'How does a Digital Evidence Seal (SureEvidence) make electronic court orders, land searches, and council certificates valid in court under Section 84 of the Evidence Act?', 'Issue and verify tamper-proof digital official records that satisfy Nigerian court admissibility rules without requiring expensive software licenses. Digital seals embed verifiable document signatures, issuing device hardware details, automated counters, and legal compliance attestations into standard high-resolution QR codes printed on official forms.', 'NS-RFC-005');
INSERT INTO ngstack_global_search_fts VALUES ('FAQ', 'NS-FAQ-04', '/governance#' || 'NS-FAQ-04', 'How does Direct Treasury Settlement (SplitDirect) guarantee that court fees, state taxes, and 774 Local Government revenues go straight to official public accounts?', 'Set up public payment channels for court filings, property rates, and municipal market fees that deposit revenues 100% directly into government treasuries. In accordance with Section 121(3) of the Constitution and Supreme Court ruling SC/CV/343/2024, direct settlement rules prohibit holding public revenue in private middleman accounts or state joint holding accounts.', 'NS-RFC-009 NS-RFC-014');
INSERT INTO ngstack_global_search_fts VALUES ('FAQ', 'NS-FAQ-05', '/governance#' || 'NS-FAQ-05', 'How do local courts, primary health clinics, and local government offices keep working when the power or mobile network goes down?', 'Run a lightweight, offline-first registry web application across remote public offices without relying on continuous power or mobile internet. The offline registry engine uses a tiny app download under 35 KB that stores records securely on the local device and synchronizes automatically whenever internet connection is restored.', 'NS-RFC-004');
INSERT INTO ngstack_global_search_fts VALUES ('FAQ', 'NS-FAQ-06', '/governance#' || 'NS-FAQ-06', 'How does the 774 Local Government Stack stop roadside cash touting (agbero extortion), fake market tickets, and multiple taxation of commercial vehicles?', 'Issue and verify shop permits, market tickets, and inter-council vehicle transit passes using secure digital checks. Official fees paid by simple feature-phone USSD codes (*347*LGA#) or mobile payment terminals deposit 100% into council treasury accounts and generate instant digital QR passes.', 'NS-RFC-009 NS-RFC-014');
INSERT INTO ngstack_global_search_fts VALUES ('FAQ', 'NS-FAQ-07', '/governance#' || 'NS-FAQ-07', 'How does Digital Indigene & Residency Attestation (IndigeneProof) end forged paper letters and weeks of waiting at local council headquarters?', 'Apply for or verify official local government indigene and residency certificates for job, military, police, or university applications. Digital indigene processes link clear citizen consent to simple USSD endorsement by recognized ward leaders and secure digital signatures from local council officials.', 'NS-RFC-005 NS-RFC-006 NS-RFC-014');
INSERT INTO ngstack_global_search_fts VALUES ('FAQ', 'NS-FAQ-08', '/governance#' || 'NS-FAQ-08', 'Can a citizen without a smartphone, internet data plan, or biometric token be turned away from local council, health, or court services?', 'Access public services like grievance reporting, vital registrations, market ticketing, or local healthcare using basic phones or walk-in service desks. The Non-Exclusion Guarantee mandates that every service remains accessible via simple USSD codes (*347*LGA#), SMS notifications in five local languages (English, Hausa, Yoruba, Igbo, and Pidgin), and standard paper counter options.', 'NS-RFC-001 NS-RFC-014');
INSERT INTO ngstack_global_search_fts VALUES ('FAQ', 'NS-FAQ-09', '/governance#' || 'NS-FAQ-09', 'How do citizens and small businesses control who sees their personal or financial records under the Nigeria Data Protection Act 2023?', 'Manage clear data sharing approvals, expiration limits, and instant permission cancellations for banking, tax, health, and legal services. Under data privacy standards, every shared data permission carries a clear expiration time and explicit purpose; revoking access stops data sharing across connected systems within 60 seconds.', 'NS-RFC-006');
INSERT INTO ngstack_global_search_fts VALUES ('FAQ', 'NS-FAQ-10', '/governance#' || 'NS-FAQ-10', 'How does Safe Transaction Retry (Confluence) stop customers from being debited twice when a bank transfer or filing times out?', 'Prevent duplicate payments and repeated submissions when mobile network or banking connections experience delays. System transport rules attach unique operation references to every transaction, safely holding dropped connections in an unresolved state rather than marking them as instant failures.', 'NS-RFC-002 NS-RFC-003');
INSERT INTO ngstack_global_search_fts VALUES ('FAQ', 'NS-FAQ-11', '/governance#' || 'NS-FAQ-11', 'Why does Nigeria Stack ban lawyer "win-rate" rankings and lock sensitive family and juvenile court files?', 'Access court records, legal appearances, and case summaries while complying with legal ethics and privacy laws. Legal specifications enforce neutral case outcome descriptions, official lawyer bar numbers, and strict row-level database security under Nigerian Bar Association Rule 39 and privacy laws.', 'NS-RFC-004 NS-RFC-013 NS-RFC-014');
INSERT INTO ngstack_global_search_fts VALUES ('FAQ', 'NS-FAQ-12', '/governance#' || 'NS-FAQ-12', 'How does GivePower keep AI assistants safe so they cannot move money or file official records without human approval?', 'Integrate automated AI tools and assistant workflows under secure delegation rules. Delegation standards enforce read-only access by default for AI tools, require human approval for official actions or updates, and place micro-payments into temporary holding that returns funds if a service fails.', 'NS-RFC-008');
INSERT INTO ngstack_global_search_fts VALUES ('FAQ', 'NS-FAQ-13', '/governance#' || 'NS-FAQ-13', 'Why does the 32-Industry Directory highlight existing Nigerian tech platforms first, and why does the State & Local Government Atlas avoid subjective ranking scores?', 'Review accurate technology coverage maps across 32 Nigerian economic sectors, 36 States, the FCT, and 774 Local Government Areas. Industry mapping highlights established domestic technology providers—including NIBSS, Paystack, Moniepoint, Remita, Shipbubble, Termii, Dojah, Helium Health, and AFEX—before identifying service gaps, while subnational maps list verified statuses like Live Digital Service, Active Pilot, Paper-Only Registry, or Not Yet Assessed.', 'NS-RFC-001 NS-RFC-014');
INSERT INTO ngstack_global_search_fts VALUES ('FAQ', 'NS-FAQ-14', '/governance#' || 'NS-FAQ-14', 'How does Nigeria Stack meet the Five Public Safeguards of Open Digital Infrastructure (Freedom to Exit, Open Source Code, Verifiable Audit, Inclusive Governance, and Freedom to Replicate)?', 'Inspect, adapt, or self-host Nigeria Stack specifications and developer toolkits on state, local government, or private infrastructure. All specifications and datasets are published under public domain licenses (CC0-1.0), developer toolkits use open licenses, registries publish daily verification logs, working groups manage standards transparently, and open keys allow independent hosting.', 'NS-RFC-001 NS-RFC-002 NS-RFC-005 NS-RFC-009');
INSERT INTO ngstack_global_search_fts VALUES ('FAQ', 'NS-FAQ-15', '/governance#' || 'NS-FAQ-15', 'How do Digital Land & Farm Boundary Checks (LandGuard & AgriTrust) stop double-allocation of customary land and fraudulent property sales?', 'Verify whether a town plot, rural farm boundary, or local customary land right is free of ongoing court disputes or conflicting claims. Land and agricultural verification tools connect mapped farm and plot boundaries directly to state court dispute registries and local customary court case logs.', 'NS-RFC-012 NS-RFC-014');
INSERT INTO ngstack_global_search_fts VALUES ('RAG_BENCHMARK', 'RAG-H2-01', '/', 'What is Nigeria Stack and how does it stay independent of government agencies and private vendors?', 'Nigeria Stack (nigeriastack.org) is a CC0-1.0 Public Domain open technical specification and conformance commons for Nigeria''s digital infrastructure across 32 industries and 774 Local Government Areas. Its Four-Wall Anti-Capture Firewall prevents it from processing payments, brokering paid APIs, impersonating public institutions, or selling proprietary software catalogs.', 'NS-KB-01 NS-RFC-001');
INSERT INTO ngstack_global_search_fts VALUES ('RAG_BENCHMARK', 'RAG-H2-02', '/', 'How do the five layers of the Nigeria Stack connect public registries and private sector apps without centralizing databases?', 'The 5-Layer Hourglass connects local apps and central systems without aggregating master databases. Layer 1 powers offline 2G/WASM apps; Layer 2 references statutory identity (NIN, BVN, TIN, CAC, SCN) and direct treasury routes; Layer 3 standardizes local registries and legal proof; Layer 4 handles async transport, consent, and market links; Layer 5 coordinates 32 sector networks.', 'NS-RFC-001');
INSERT INTO ngstack_global_search_fts VALUES ('RAG_BENCHMARK', 'RAG-H2-03', '/', 'How does Nigeria Stack guarantee citizens'' right to exit, open-source code, public audits, and self-hosting?', 'Nigeria Stack passes five DPI tests: 01 Exit (instant data export, under-60-second consent revocation, USSD non-exclusion), 02 Code (Public Domain specs and Apache-2.0 SDKs), 03 Audit (daily cryptographic proof logs), 04 Govern (transparent multi-stakeholder working groups), and 05 Fork (decentralized self-hosting), displaying Evidence, Components, Framework, and Methods on all specifications.', 'NS-KB-01 NS-RFC-002 NS-RFC-005 NS-RFC-009');
INSERT INTO ngstack_global_search_fts VALUES ('RAG_BENCHMARK', 'RAG-H2-04', '/sectors', 'What are the eight everyday digital bottlenecks slowing down Nigeria''s 32 industries?', 'The stack solves eight systemic friction points: restricted data access (MECH-01), uneven state/LGA coverage (MECH-02), incompatible data formats (MECH-03), multi-party payment timeouts (MECH-04), weak digital evidence trust (MECH-05), offline network drops (MECH-06), high aggregator fees (MECH-07), and unindexed paper-based legal statutes (MECH-08).', 'NS-KB-03A');
INSERT INTO ngstack_global_search_fts VALUES ('RAG_BENCHMARK', 'RAG-H2-05', '/sectors', 'How does Nigeria Stack work alongside existing Nigerian payment, identity, logistics, and health platforms?', 'Across 32 industries, Nigeria Stack builds on existing live services—such as NIBSS, Paystack, Moniepoint, Remita, Shipbubble, Termii, Dojah, Workpay, Curacel, Helium Health, and AFEX—providing open protocols for consent, verification, evidence generation, and multi-party settlement to bridge missing inter-platform links.', 'NS-KB-03A');
INSERT INTO ngstack_global_search_fts VALUES ('RAG_BENCHMARK', 'RAG-H2-06', '/protocols/sure-evidence', 'How does SureEvidence make electronic court orders, land searches, and local council certificates admissible under Section 84 of the Evidence Act?', 'SureEvidence (NS-RFC-005) package digital copies, land registry filings, university diplomas, and municipal origin certificates into verifiable digital credentials. Each record contains a cryptographic hash, hardware signature, tamper-proof timestamp, statutory regularity declaration under Evidence Act Section 84(2)/(4), and an offline-scannable high-resolution QR code.', 'NS-RFC-005');
INSERT INTO ngstack_global_search_fts VALUES ('RAG_BENCHMARK', 'RAG-H2-07', '/protocols/clearam-consent', 'How does ClearAm let citizens and businesses control their data and revoke consent in under 60 seconds under the NDPA 2023?', 'ClearAm (NS-RFC-006) attaches statutory privacy envelopes to data requests under the Nigeria Data Protection Act 2023. Requests specify exact purpose categories (finance, health, law, education, agriculture, municipal) and expiration times. If consent expires or is revoked by the user, gateway servers immediately block further access in under 60 seconds.', 'NS-RFC-006 NS-KB-09');
INSERT INTO ngstack_global_search_fts VALUES ('RAG_BENCHMARK', 'RAG-H2-08', '/protocols/confluence-gateway', 'How does Confluence prevent double debits and duplicate filings when Nigerian mobile networks drop?', 'Confluence (NS-RFC-002 & NS-RFC-003) uses signed asynchronous transaction states. When network connections drop mid-transaction, requests enter a locked verification state instead of failing blindly. Duplicate retries are held until reconciliation completes, ensuring users are never double-charged or issued duplicate filings during outages.', 'NS-RFC-002 NS-RFC-003');
INSERT INTO ngstack_global_search_fts VALUES ('RAG_BENCHMARK', 'RAG-H2-09', '/protocols/marketlink-commerce', 'How do MarketLink, PassCargo, and AgriTrust help merchants, clearing agents, and smallholder farmers trade without monopoly fees?', 'MarketLink (NS-RFC-007) connects product catalogs and delivery logistics without commission middleman markups; PassCargo (NS-RFC-010) streamlines customs, port, and health inspection clearances into instant exit tokens; and AgriTrust (NS-RFC-012) links digital farm boundary surveys directly to verifiable warehouse receipts for fair crop financing.', 'NS-RFC-007 NS-RFC-010 NS-RFC-012');
INSERT INTO ngstack_global_search_fts VALUES ('RAG_BENCHMARK', 'RAG-H2-10', '/protocols/givepower-agents', 'How does GivePower keep AI assistants safe with mandatory human approval and protected micro-payments?', 'GivePower (NS-RFC-008) sets strict guardrails for automated AI tools: read-only default data access, explicit biometric or cryptographic human approval for official state actions under NDPA Section 37, and micro-payment escrows that release funds only after verified successful API completions.', 'NS-RFC-008');
INSERT INTO ngstack_global_search_fts VALUES ('RAG_BENCHMARK', 'RAG-H2-11', '/protocols/kioskbase-registries', 'How does KioskBase keep local courts, primary health clinics, and council offices running during power and internet outages?', 'KioskBase (NS-RFC-004) packages a lightweight web app (under 35 KB) backed by an in-browser local database. Frontline staff in rural areas can log records offline; updates auto-synchronize without data loss once connection restores, while strict privacy locks shield sensitive patient and minor files.', 'NS-RFC-004');
INSERT INTO ngstack_global_search_fts VALUES ('RAG_BENCHMARK', 'RAG-H2-12', '/protocols/lawtree-ast', 'How does LawTree publish up-to-date Nigerian federal and state laws with verified translations in Hausa, Yoruba, Igbo, and Pidgin?', 'LawTree (NS-RFC-013) parses Federal and State statutes into structured legal records linked directly to Official Gazette source citations. It tracks historical amendments accurately and ensures legal translations across English, Hausa, Yoruba, Igbo, and Pidgin undergo certified legal review before public display.', 'NS-RFC-013');
INSERT INTO ngstack_global_search_fts VALUES ('RAG_BENCHMARK', 'RAG-H2-13', '/protocols/lga-governance-stack', 'How does the 774 Local Government Stack deliver constitutional municipal services and route revenue directly to local council treasuries?', 'LgaGovernanceStack (NS-RFC-014) standardizes 14 municipal service modules (from civic registry to street listing) across all 774 LGAs and Area Councils. In line with Supreme Court Ruling SC/CV/343/2024, local collection routes payments directly to official council accounts without intermediary diversion, offering USSD access (*347*LGA#) for non-smartphone users.', 'NS-RFC-009 NS-RFC-014 NS-KB-03C NS-KB-03D');
INSERT INTO ngstack_global_search_fts VALUES ('RAG_BENCHMARK', 'RAG-H2-14', '/conformance', 'How can ministries, states, local councils, banks, and developers test and certify their systems for free in the browser?', 'Software builders and institutions can run real-time compliance tests inside a browser WebAssembly sandbox without storing data on central servers, or use open command-line tools against automated test suites. Conformance passes generate downloadable, cryptographically signed receipts instantly at no cost.', 'NS-KB-04B NS-KB-09');
INSERT INTO ngstack_global_search_fts VALUES ('RAG_BENCHMARK', 'RAG-H2-15', '/atlas', 'How does the Sub-National Readiness Atlas track digital public services across all 36 States, the FCT, and 774 Local Government Areas without fabricated rankings?', 'The Sub-National Atlas (NS-KB-03B & NS-KB-03C) audits 36 States, the FCT, and 774 Local Government Areas across 8 digital infrastructure dimensions. Instead of subjective league tables, it reports verifiable status categories—Verified Live, Corroborated Pilot, Paper-Bound Gap, and Unassessed—ensuring transparent and factual public monitoring.', 'NS-KB-03B NS-KB-03C');
